catalog_script_client.script:
function onChange(control, oldValue, newValue, isLoading) {

    // Se o formulário estiver a carregar, ou se o campo for limpo, não fazer nada
    if (isLoading || newValue === '') {
        g_form.clearValue('max_capacity'); // Limpa o campo de lotação
        return;
    }

    // 1. Chamar o GlideAjax (o nosso "Buscador")
    var ga = new GlideAjax('x_1836079_office.BaseUtils'); // O seu Script Include
    ga.addParam('sysparm_name', 'getBaseMaxCapacity'); // A nossa nova função

    // 2. Enviar o sys_id da Base que o utilizador acabou de selecionar
    ga.addParam('sysparm_base_id', newValue); 

    // 3. Chamar o servidor (de forma assíncrona) e definir a função de callback
    ga.getXML(populateCapacity);
}

// 4. Função "Callback" (o que fazer quando o servidor responder)
function populateCapacity(response) {
    // Pega a resposta (o '0' ou '10' ou '20') do Script Include
    var answer = response.responseXML.documentElement.getAttribute("answer");

    // 5. Preenche a sua variável 'max_capacity' (que é read-only) com a resposta
    g_form.setValue('max_capacity', answer);
}
